//! Dimensions, leaders, tolerances, dimension styles and the annotation scale.
//!
//! `Command::Dimension(DimSpec)` adds real Dimension entities on the current layer, in the
//! current dimension style, each with its anonymous `*D` block generated by
//! `qiyas_geom::dimension_entities` (lines, Solid arrowheads, a Text), so AutoCAD shows them as
//! Qiyas does. `DimEdit` (text override, flip, move text) and find and replace rebuild that block
//! in the same step. `DimBreak` and `DimJogLine` change the block's lines only (a later rebuild
//! drops them); `DimSpace` moves dimension lines to an equal spacing.
//!
//! The annotation scale (`AnnotationScale`, CANNOSCALE, e.g. "1:50") multiplies the sizes of new
//! annotations: a dimension, leader or tolerance keeps its style's DIMSCALE times it as its own
//! DIMSCALE override (AutoCAD's `DSTYLE` xdata), so it draws the same everywhere. No per-object
//! annotation scale lists: AutoCAD does not see these as annotative.

use opencadcodec::entities::{
    AttachmentPoint, Dimension, DimensionAligned, DimensionAngular3Pt, DimensionArc,
    DimensionDiameter, DimensionLinear, DimensionOrdinate, DimensionRadius, Leader,
    LeaderCreationType, Tolerance,
};
use opencadcodec::tables::DimStyle;
use opencadcodec::{BlockRecord, CadDocument, EntityType, Handle, MText, Vector3};
use opencadkernel::geom2d::Curve;
use qiyas_geom::{
    clear_dimpost, dimension_entities, dimpost, flatten, is_logical_text, set_dimpost,
    set_dimscale, snap_shapes, style_named, DimLook, Xform,
};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use serde_json::json;

use crate::text::{escape_mtext, mark_logical};
use crate::{CoreError, Session, Target, Units};

/// A dimension to add (`Command::Dimension`). Points are in drawing coordinates, angles in
/// degrees. Circles and arcs are picked as `Target`s at the top of the sheet.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum DimSpec {
    /// The distance from `p1` to `p2` along `rotation` (degrees), its line through `line_point`.
    /// No rotation: horizontal, or vertical when `line_point` lies beside the points rather than
    /// above or below them (AutoCAD's DIMLINEAR).
    #[schemars(example = json!({"kind": "linear", "p1": [0, 0], "p2": [5, 0], "line_point": [2.5, -1]}))]
    #[schemars(extend("x-words" = ["DIMLINEAR", "DLI"]))]
    Linear {
        p1: [f64; 2],
        p2: [f64; 2],
        line_point: [f64; 2],
        #[serde(default)]
        rotation: Option<f64>,
    },
    /// The true distance from `p1` to `p2`, its line `offset` to their left (negative: right).
    #[schemars(example = json!({"kind": "aligned", "p1": [0, 0], "p2": [3, 4], "offset": 0.8}))]
    #[schemars(extend("x-words" = ["DIMALIGNED", "DAL"]))]
    Aligned {
        p1: [f64; 2],
        p2: [f64; 2],
        offset: f64,
    },
    /// The angle at `vertex` from `p1` to `p2`, its arc through `arc_point`.
    #[schemars(example = json!({"kind": "angular", "vertex": [0, 0], "p1": [5, 0], "p2": [0, 5], "arc_point": [2, 2]}))]
    #[schemars(extend("x-words" = ["DIMANGULAR", "DAN"]))]
    Angular {
        vertex: [f64; 2],
        p1: [f64; 2],
        p2: [f64; 2],
        arc_point: [f64; 2],
    },
    /// The radius of a circle or arc, with its text at `point`. Pick clear space outside the curve.
    #[schemars(example = json!({"kind": "radius", "target": {"handle": 1234}, "point": [3, 3]}))]
    #[schemars(extend("x-words" = ["DIMRADIUS", "DRA"]))]
    Radius { target: Target, point: [f64; 2] },
    /// The diameter of a circle or arc, with its text at `point` along that direction.
    #[schemars(example = json!({"kind": "diameter", "target": {"handle": 1234}, "point": [3, 3]}))]
    #[schemars(extend("x-words" = ["DIMDIAMETER", "DDI"]))]
    Diameter { target: Target, point: [f64; 2] },
    /// The length of an arc, its dimension arc through `point`.
    #[schemars(example = json!({"kind": "arc_length", "target": {"handle": 1234}, "point": [1, 1.5]}))]
    #[schemars(extend("x-words" = ["DIMARC", "DAR"]))]
    ArcLength { target: Target, point: [f64; 2] },
    /// The X (leader mostly up or down) or Y ordinate of `feature` from the drawing's origin.
    #[schemars(example = json!({"kind": "ordinate", "feature": [5, 3], "leader_end": [5, 6]}))]
    #[schemars(extend("x-words" = ["DIMORDINATE", "DOR"]))]
    Ordinate {
        feature: [f64; 2],
        leader_end: [f64; 2],
    },
    /// Dimensions from the first point of the linear or aligned dimension `from` to each of
    /// `points`, each line a baseline spacing (DIMDLI) further out.
    #[schemars(example = json!({"kind": "baseline", "from": {"handle": 1234}, "points": [[8, 0], [12, 0]]}))]
    #[schemars(extend("x-words" = ["DIMBASELINE", "DBA"]))]
    Baseline {
        from: Target,
        points: crate::PointRun,
    },
    /// Dimensions on the line of `from`, from its second point to the first of `points`, then
    /// from each point to the next.
    #[schemars(example = json!({"kind": "continue", "from": {"handle": 1234}, "points": [[8, 0], [12, 0]]}))]
    #[schemars(extend("x-words" = ["DIMCONTINUE", "DCO"]))]
    Continue {
        from: Target,
        points: crate::PointRun,
    },
    /// One dimension per entity: a line its horizontal or vertical length (its line through
    /// `line_point`), an arc its radius, a circle its diameter.
    #[schemars(example = json!({"kind": "quick", "targets": [{"handle": 1234}, {"handle": 1235}], "line_point": [0, -1.5]}))]
    #[schemars(extend("x-words" = ["QDIM"]))]
    Quick {
        targets: Vec<Target>,
        line_point: [f64; 2],
    },
}

/// What `Command::DimEdit` changes on a dimension.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum DimEditOp {
    /// The text shown instead of the measurement; `<>` stands for it, empty clears the override.
    TextOverride(String),
    /// Turns both arrowheads round.
    Flip,
    /// Puts the text's middle at this point.
    MoveText([f64; 2]),
}

/// The common fields of a dimension style, in drawing units (before its scale).
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize, JsonSchema)]
pub struct DimStyleFields {
    /// DIMASZ.
    pub arrow_size: f64,
    /// DIMTXT.
    pub text_height: f64,
    /// DIMDEC: decimal places, 0 to 8.
    pub precision: i16,
    /// DIMEXO.
    pub ext_offset: f64,
    /// DIMEXE.
    pub ext_extension: f64,
    /// DIMGAP.
    pub gap: f64,
    /// DIMSCALE: every size above times this.
    pub scale: f64,
    /// Show the drawing's unit after the number ("12 m"): a DIMPOST suffix Qiyas gives the
    /// dimensions it makes when the style has none of its own. On unless turned off.
    #[serde(default = "yes")]
    pub show_units: bool,
}

fn yes() -> bool {
    true
}

impl DimStyleFields {
    fn of(style: &DimStyle, show_units: bool) -> Self {
        DimStyleFields {
            arrow_size: style.dimasz,
            text_height: style.dimtxt,
            precision: style.dimdec,
            ext_offset: style.dimexo,
            ext_extension: style.dimexe,
            gap: style.dimgap,
            scale: style.dimscale,
            show_units,
        }
    }

    fn check(&self) -> Result<(), CoreError> {
        let sizes = [
            self.arrow_size,
            self.ext_offset,
            self.ext_extension,
            self.gap,
        ];
        if !sizes.iter().all(|v| v.is_finite() && *v >= 0.0) {
            return Err(invalid("Sizes must be 0 or more"));
        }
        if !(self.text_height > 0.0 && self.text_height.is_finite()) {
            return Err(invalid("The text height must be more than 0"));
        }
        if !(0..=8).contains(&self.precision) {
            return Err(invalid("The precision is 0 to 8 decimal places"));
        }
        if !(self.scale > 0.0 && self.scale.is_finite()) {
            return Err(invalid("The scale must be more than 0"));
        }
        Ok(())
    }

    fn apply(&self, style: &mut DimStyle) {
        style.dimasz = self.arrow_size;
        style.dimtxt = self.text_height;
        style.dimdec = self.precision;
        style.dimexo = self.ext_offset;
        style.dimexe = self.ext_extension;
        style.dimgap = self.gap;
        style.dimscale = self.scale;
    }
}

/// A dimension style as the style panel shows it.
#[derive(Debug, Clone, Serialize)]
pub struct DimStyleInfo {
    pub name: String,
    pub fields: DimStyleFields,
}

/// Every suffix Qiyas gives a dimension for its drawing's units.
const UNIT_POSTS: [&str; 5] = ["<> m", "<> cm", "<> mm", "<>\"", "<>'"];

/// Whether a DIMPOST holds no suffix: empty, or just the number (`<>`), as the codec's own
/// styles have it.
fn no_suffix(post: &str) -> bool {
    matches!(post.trim(), "" | "<>")
}

/// The drawing variable that holds the "Show units" switch of the dimension style `name`: "0"
/// when it is off (no variable: on).
fn units_variable(name: &str) -> String {
    format!("QIYAS_DIMUNITS_{name}")
}

type P = [f64; 2];
/// A linear or aligned dimension's two points, its line point and its axis.
type LinearParts = (P, P, P, P);
/// A circle or an arc as drawn: centre, radius, and for an arc its start and end angles.
type Round = (P, f64, Option<(f64, f64)>);
/// A line of a dimension's block: its handle and its two ends.
type BlockLine = (Handle, P, P);

fn invalid(why: impl Into<String>) -> CoreError {
    CoreError::InvalidCommand(why.into())
}

fn finite(points: &[[f64; 2]]) -> Result<(), CoreError> {
    if points.iter().flatten().all(|v| v.is_finite()) {
        Ok(())
    } else {
        Err(invalid("The points must have finite coordinates"))
    }
}

fn v3(p: [f64; 2]) -> Vector3 {
    Vector3::new(p[0], p[1], 0.0)
}

fn sub(a: [f64; 2], b: [f64; 2]) -> [f64; 2] {
    [a[0] - b[0], a[1] - b[1]]
}

fn dot(a: [f64; 2], b: [f64; 2]) -> f64 {
    a[0] * b[0] + a[1] * b[1]
}

fn unit(a: [f64; 2]) -> Option<[f64; 2]> {
    let l = a[0].hypot(a[1]);
    (l > 1e-12 && l.is_finite()).then(|| [a[0] / l, a[1] / l])
}

fn xy(v: &Vector3) -> [f64; 2] {
    [v.x, v.y]
}

/// The scale "a:b" (paper : drawing, e.g. "1:50") as drawing units per paper unit (50).
fn scale_factor(name: &str) -> Option<f64> {
    let (a, b) = name.split_once(':')?;
    let (a, b): (f64, f64) = (a.trim().parse().ok()?, b.trim().parse().ok()?);
    (a > 0.0 && b > 0.0 && a.is_finite() && b.is_finite()).then(|| b / a)
}

/// A linear dimension of `p1` to `p2` along `angle` (radians), its line through `line_point`.
fn linear_dimension(p1: [f64; 2], p2: [f64; 2], line_point: [f64; 2], angle: f64) -> Dimension {
    let mut d = DimensionLinear::new(v3(p1), v3(p2));
    d.rotation = angle;
    let n = [-angle.sin(), angle.cos()];
    let off = dot(sub(line_point, p2), n);
    let mut d = Dimension::Linear(d);
    d.set_definition_point(v3([p2[0] + n[0] * off, p2[1] + n[1] * off]));
    d
}

/// Horizontal (0) or vertical (90 degrees) for a line through `line_point`: vertical when it lies
/// further beside the points than above or below them.
pub(crate) fn auto_angle(p1: [f64; 2], p2: [f64; 2], line_point: [f64; 2]) -> f64 {
    let outside = |v: f64, a: f64, b: f64| (a.min(b) - v).max(v - a.max(b)).max(0.0);
    let beside = outside(line_point[0], p1[0], p2[0]);
    let above = outside(line_point[1], p1[1], p2[1]);
    if beside > above {
        std::f64::consts::FRAC_PI_2
    } else {
        0.0
    }
}

/// A linear or aligned dimension's two points, its line point and its axis.
fn linear_parts(d: &Dimension) -> Option<LinearParts> {
    match d {
        Dimension::Linear(l) => Some((
            xy(&l.first_point),
            xy(&l.second_point),
            xy(&l.definition_point),
            [l.rotation.cos(), l.rotation.sin()],
        )),
        Dimension::Aligned(a) => Some((
            xy(&a.first_point),
            xy(&a.second_point),
            xy(&a.definition_point),
            unit(sub(xy(&a.second_point), xy(&a.first_point))).unwrap_or([1.0, 0.0]),
        )),
        _ => None,
    }
}

impl Session {
    /// The dimension style new dimensions take: the drawing's current one (DIMSTYLE), else
    /// Standard.
    pub fn dim_style(&self) -> String {
        let doc = &self.drawing.doc;
        doc.dim_styles
            .get(&doc.header.current_dimstyle_name)
            .or_else(|| doc.dim_styles.get("Standard"))
            .map_or_else(|| "Standard".to_string(), |s| s.name.clone())
    }

    /// The drawing's own dimension styles (not an xref's), sorted by name.
    pub fn dim_styles(&self) -> Vec<DimStyleInfo> {
        let mut out: Vec<DimStyleInfo> = self
            .drawing
            .doc
            .dim_styles
            .iter()
            .filter(|s| !s.name.contains('|') && !s.name.is_empty())
            .map(|s| DimStyleInfo {
                name: s.name.clone(),
                fields: DimStyleFields::of(s, self.dim_units_shown(&s.name)),
            })
            .collect();
        out.sort_by(|a, b| a.name.cmp(&b.name));
        out
    }

    /// The annotation scale (CANNOSCALE, "1:1" when the drawing has none) and the drawing units
    /// per paper unit it gives (50 for "1:50").
    pub fn annotation_scale(&self) -> (String, f64) {
        let doc = &self.drawing.doc;
        let name = doc
            .drawing_variable("CANNOSCALE")
            .map(str::to_string)
            .filter(|n| !n.trim().is_empty())
            .unwrap_or_else(|| doc.header.current_annotation_scale.clone());
        let value = doc.header.annotation_scale_value;
        let factor = scale_factor(&name)
            .or_else(|| (value > 0.0 && value.is_finite()).then(|| 1.0 / value))
            .unwrap_or(1.0);
        (name, factor)
    }

    /// `Command::AnnotationScale`: CANNOSCALE becomes `name` ("paper:drawing", e.g. "1:50").
    pub(crate) fn set_annotation_scale(&mut self, name: &str) -> Result<(), CoreError> {
        let name = name.trim();
        let factor = scale_factor(name)
            .ok_or_else(|| invalid(format!("{name} is no scale: write it as 1:50")))?;
        let doc = &mut self.drawing.doc;
        doc.header.current_annotation_scale = name.to_string();
        doc.header.annotation_scale_value = 1.0 / factor;
        if !doc.set_drawing_variable("CANNOSCALE", name) {
            return Err(invalid("The drawing's variables could not take the scale"));
        }
        Ok(())
    }

    /// `Command::SetDimStyle`: the style `name` (made from the current one when the drawing has
    /// none of that name) takes `fields`; with `current`, new dimensions take it.
    pub(crate) fn set_dim_style(
        &mut self,
        name: &str,
        fields: &DimStyleFields,
        current: bool,
    ) -> Result<(), CoreError> {
        fields.check()?;
        let name = name.trim();
        if name.is_empty()
            || name.contains(['|', '<', '>', '/', '\\', '"', ':', ';', '?', '*', '=', '`'])
        {
            return Err(invalid("Give the style a name without |<>/\\\":;?*=`"));
        }
        let from = self.dim_style();
        let units_before = self.dim_units_shown(name);
        let doc = &mut self.drawing.doc;
        if doc.dim_styles.get(name).is_none() {
            let mut style = doc
                .dim_styles
                .get(&from)
                .cloned()
                .unwrap_or_else(DimStyle::standard);
            style.name = name.to_string();
            style.handle = doc.allocate_handle();
            doc.dim_styles
                .add(style)
                .map_err(|e| invalid(e.to_string()))?;
        }
        let style = doc.dim_styles.get_mut(name).expect("added above");
        let before = style.clone();
        fields.apply(style);
        let changed = *style != before;
        let (name, handle) = (style.name.clone(), style.handle);
        let is_current = current || doc.header.current_dimstyle_name.eq_ignore_ascii_case(&name);
        if is_current {
            let h = &mut doc.header;
            h.current_dimstyle_name = name.clone();
            h.current_dimstyle_handle = handle;
            h.dim_arrow_size = fields.arrow_size;
            h.dim_text_height = fields.text_height;
            h.dim_decimal_places = fields.precision;
            h.dim_ext_line_offset = fields.ext_offset;
            h.dim_ext_line_extension = fields.ext_extension;
            h.dim_line_gap = fields.gap;
            h.dim_scale = fields.scale;
        }
        let units_changed = fields.show_units != units_before;
        if units_changed {
            let value = if fields.show_units { "1" } else { "0" };
            if !self
                .drawing
                .doc
                .set_drawing_variable(&units_variable(&name), value)
            {
                return Err(invalid("The drawing's variables could not take the switch"));
            }
        }
        if changed || units_changed {
            for h in self.generated_dimensions(&name) {
                // Turning the switch is what puts the unit on, or takes it off, the style's
                // dimensions; any other edit rebuilds them as they are.
                if units_changed {
                    self.apply_unit_suffix(h);
                }
                self.rebuild_dimension(h)?;
            }
        }
        Ok(())
    }

    /// Whether the dimension style `name` shows the drawing's unit after the number (its "Show
    /// units" switch, kept in the drawing's variables only once turned off).
    pub fn dim_units_shown(&self, name: &str) -> bool {
        self.drawing.doc.drawing_variable(&units_variable(name)) != Some("0")
    }

    /// The DIMPOST suffix for the drawing's units: " m", " cm", " mm", `"` or `'` after the
    /// number. Units the header does not name are millimetres, as everywhere in Qiyas.
    fn unit_post(&self) -> &'static str {
        match Units::from_header(self.drawing.doc.header.insertion_units) {
            Units::Metres => "<> m",
            Units::Centimetres => "<> cm",
            Units::Millimetres | Units::Unknown => "<> mm",
            Units::Inches => "<>\"",
            Units::Feet => "<>'",
        }
    }

    /// Gives the dimension `h` the unit suffix, or takes it off, as its style says: a DIMPOST
    /// override on the dimension itself (how AutoCAD keeps a suffix set on one dimension), only
    /// when its style has no suffix of its own, its "Show units" switch is on and its numbers are
    /// in drawing units (DIMLFAC 1). A suffix of any other kind on the dimension is left alone.
    fn apply_unit_suffix(&mut self, h: Handle) {
        let post = self.unit_post();
        let doc = &self.drawing.doc;
        let Some(EntityType::Dimension(d)) = doc.get_entity(h) else {
            return;
        };
        let base = d.base();
        let style = style_named(doc, &base.style_name);
        let measures_length = !matches!(d, Dimension::Angular2Ln(_) | Dimension::Angular3Pt(_));
        // DIMLFAC 0 reads as 1 (see `DimLook`).
        let factor = if style.dimlfac.is_finite() && style.dimlfac != 0.0 {
            style.dimlfac
        } else {
            1.0
        };
        // A layout's numbers are paper units, not the drawing's: no suffix there.
        let in_model = doc
            .block_records
            .get("*Model_Space")
            .is_some_and(|m| m.handle == base.common.owner_handle);
        let wanted = measures_length
            && in_model
            && no_suffix(&style.dimpost)
            && (factor - 1.0).abs() < 1e-12
            && self.dim_units_shown(&base.style_name);
        let own = dimpost(&base.common);
        // A suffix that is not one of ours is somebody's choice.
        if own.as_deref().is_some_and(|p| !UNIT_POSTS.contains(&p)) {
            return;
        }
        if (own.as_deref() == Some(post) && wanted) || (own.is_none() && !wanted) {
            return;
        }
        // A DWG read keeps each application's xdata as the bytes it came in, and writes those
        // back over the edited record: drop ACAD's so the edit is what is saved.
        let acad = self
            .drawing
            .doc
            .app_ids
            .get("ACAD")
            .map(|a| a.handle.value());
        if let Some(EntityType::Dimension(d)) = self.drawing.doc.get_entity_mut(h) {
            let common = &mut d.base_mut().common;
            if wanted {
                set_dimpost(common, post);
            } else {
                clear_dimpost(common);
            }
            if let Some(acad) = acad {
                common
                    .extended_data
                    .raw_dwg_eed
                    .retain(|(app, _)| *app != acad);
            }
        }
    }

    /// The dimensions at the top of every sheet in the style `name` whose block Qiyas generated
    /// (its parts carry `LOGICAL_TEXT_APP`); a block AutoCAD made is never rebuilt.
    fn generated_dimensions(&self, name: &str) -> Vec<Handle> {
        let doc = &self.drawing.doc;
        self.drawing
            .sheets()
            .into_iter()
            .flat_map(|sheet| self.drawing.entities_in(&sheet.block).collect::<Vec<_>>())
            .filter_map(|e| match e {
                EntityType::Dimension(d)
                    if d.base().style_name.eq_ignore_ascii_case(name)
                        && generated_block(doc, d) =>
                {
                    Some(d.base().common.handle)
                }
                _ => None,
            })
            .collect()
    }

    /// The dimension `h` took another style: a Qiyas-made one takes the unit suffix as that
    /// style says (its own DIMPOST, DIMLFAC, Show units). AutoCAD's are left as they are.
    pub(crate) fn restyled_dimension(&mut self, h: Handle) {
        if let Some(EntityType::Dimension(d)) = self.drawing.doc.get_entity(h) {
            if generated_block(&self.drawing.doc, d) {
                self.apply_unit_suffix(h);
            }
        }
    }

    /// A dimension style nobody sized: the codec's stock "Standard" (text and arrows 0.18, offset
    /// 0.625, extension 1.25, gap 0.625, no unit at all), which a drawing gets when it was written
    /// without a style of its own (by Qiyas before its metric template, or a DXF without one).
    /// AutoCAD's own imperial Standard differs (offset 0.0625), so it is never taken for one.
    fn is_stock_style(s: &DimStyle) -> bool {
        s.dimtxt == 0.18
            && s.dimasz == 0.18
            && s.dimexo == 0.625
            && s.dimexe == 1.25
            && s.dimgap == 0.625
    }

    /// On open: in a drawing that is not in inches or feet, each stock style (`is_stock_style`)
    /// takes the metric template's sizes in the drawing's units (text and arrows 2.5 mm,
    /// offset 0.625, extension 1.25, gap 0.625, baseline 3.75, centre 2.5), and the dimensions
    /// Qiyas made in it are drawn again. In a metre drawing at 1:100 the stock sizes gave text
    /// 18 m tall and extension lines 125 m long. AutoCAD's dimensions keep their own blocks.
    pub(crate) fn size_stock_dim_styles(&mut self) {
        if matches!(self.drawing.units, Units::Inches | Units::Feet) {
            return;
        }
        let mm = 0.001 / self.drawing.units.to_metres();
        let doc = &mut self.drawing.doc;
        let current = doc.header.current_dimstyle_name.clone();
        let mut sized = Vec::new();
        for style in doc
            .dim_styles
            .iter_mut()
            .filter(|s| Self::is_stock_style(s))
        {
            style.dimtxt = 2.5 * mm;
            style.dimasz = 2.5 * mm;
            style.dimexo = 0.625 * mm;
            style.dimexe = 1.25 * mm;
            style.dimgap = 0.625 * mm;
            style.dimdli = 3.75 * mm;
            style.dimcen = 2.5 * mm;
            sized.push(style.name.clone());
        }
        if sized.iter().any(|n| n.eq_ignore_ascii_case(&current)) {
            let h = &mut doc.header;
            h.dim_text_height = 2.5 * mm;
            h.dim_arrow_size = 2.5 * mm;
            h.dim_ext_line_offset = 0.625 * mm;
            h.dim_ext_line_extension = 1.25 * mm;
            h.dim_line_gap = 0.625 * mm;
            h.dim_line_increment = 3.75 * mm;
            h.dim_center_mark = 2.5 * mm;
        }
        for name in sized {
            for h in self.generated_dimensions(&name) {
                // A dimension Qiyas can't draw again keeps the block it has.
                let _ = self.rebuild_dimension(h);
            }
        }
    }

    /// The DIMSCALE a new annotation keeps as its own: the annotation scale's factor, which
    /// replaces its style's DIMSCALE; `None` at 1:1 (it then follows its style).
    fn annotation_dimscale(&self) -> Option<f64> {
        if !self.sheet.eq_ignore_ascii_case("*Model_Space") {
            // Style lengths are in model drawing units; layout annotations use paper mm.
            return Some(self.drawing.units.to_metres() / 0.001);
        }
        let (_, factor) = self.annotation_scale();
        ((factor - 1.0).abs() >= 1e-12).then_some(factor)
    }

    /// The circle or arc `target` (at the top of the sheet) in the world: centre, radius, and
    /// for an arc its start and end angles.
    fn round(&self, target: &Target) -> Result<Round, CoreError> {
        let h = self.sheet_targets_any(std::slice::from_ref(target))?[0];
        let entity = self.entity(h);
        if !matches!(entity, EntityType::Circle(_) | EntityType::Arc(_)) {
            return Err(invalid("Pick a circle or an arc"));
        }
        let shapes = snap_shapes(
            &self.drawing.doc,
            entity,
            &Xform::identity(),
            self.measure_tol(),
        );
        match shapes.first().and_then(|s| s.pieces.first()) {
            Some(Curve::Circle(c)) => Ok((c.centre, c.radius, None)),
            Some(Curve::Arc(a)) => Ok((a.centre, a.radius, Some((a.start_angle, a.end_angle)))),
            _ => Err(invalid("This circle or arc is not round as drawn")),
        }
    }

    /// The linear or aligned dimension `target` at the top of the sheet.
    fn linear_target(&self, target: &Target) -> Result<(Handle, Dimension), CoreError> {
        let h = self.sheet_targets(std::slice::from_ref(target))?[0];
        match self.entity(h) {
            EntityType::Dimension(d) if linear_parts(d).is_some() => Ok((h, d.clone())),
            _ => Err(invalid("Pick a linear or aligned dimension")),
        }
    }

    /// The dimensions `spec` describes, not yet in the drawing.
    pub(crate) fn dimensions_of(&self, spec: DimSpec) -> Result<Vec<Dimension>, CoreError> {
        let out = match spec {
            DimSpec::Linear {
                p1,
                p2,
                line_point,
                rotation,
            } => {
                finite(&[p1, p2, line_point])?;
                let angle = match rotation {
                    Some(r) if r.is_finite() => r.to_radians(),
                    Some(_) => return Err(invalid("The rotation must be a number")),
                    None => auto_angle(p1, p2, line_point),
                };
                vec![linear_dimension(p1, p2, line_point, angle)]
            }
            DimSpec::Aligned { p1, p2, offset } => {
                finite(&[p1, p2])?;
                if !offset.is_finite() || unit(sub(p2, p1)).is_none() {
                    return Err(invalid("An aligned dimension needs two different points"));
                }
                let mut d = DimensionAligned::new(v3(p1), v3(p2));
                d.set_offset(offset);
                let at = d.definition_point;
                let mut d = Dimension::Aligned(d);
                d.set_definition_point(at);
                vec![d]
            }
            DimSpec::Angular {
                vertex,
                p1,
                p2,
                arc_point,
            } => {
                finite(&[vertex, p1, p2, arc_point])?;
                if [p1, p2, arc_point]
                    .iter()
                    .any(|p| unit(sub(*p, vertex)).is_none())
                {
                    return Err(invalid("The points must be away from the vertex"));
                }
                let mut d =
                    Dimension::Angular3Pt(DimensionAngular3Pt::new(v3(vertex), v3(p1), v3(p2)));
                d.set_definition_point(v3(arc_point));
                vec![d]
            }
            DimSpec::Radius { target, point } => {
                finite(&[point])?;
                let (c, r, _) = self.round(&target)?;
                let u = unit(sub(point, c)).unwrap_or([1.0, 0.0]);
                let on = [c[0] + u[0] * r, c[1] + u[1] * r];
                let mut dimension = DimensionRadius::new(v3(c), v3(on));
                dimension.base.text_middle_point = v3(point);
                dimension.base.text_user_positioned = true;
                vec![Dimension::Radius(dimension)]
            }
            DimSpec::Diameter { target, point } => {
                finite(&[point])?;
                let (c, r, _) = self.round(&target)?;
                let u = unit(sub(point, c)).unwrap_or([1.0, 0.0]);
                let a = [c[0] - u[0] * r, c[1] - u[1] * r];
                let b = [c[0] + u[0] * r, c[1] + u[1] * r];
                let mut dimension = DimensionDiameter::new(v3(a), v3(b));
                dimension.base.text_middle_point = v3(point);
                dimension.base.text_user_positioned = true;
                vec![Dimension::Diameter(dimension)]
            }
            DimSpec::ArcLength { target, point } => {
                finite(&[point])?;
                let (c, r, angles) = self.round(&target)?;
                let (start, end) = angles.ok_or_else(|| invalid("Pick an arc"))?;
                let at = |a: f64| v3([c[0] + r * a.cos(), c[1] + r * a.sin()]);
                let end = if end <= start {
                    end + std::f64::consts::TAU
                } else {
                    end
                };
                let mut d = DimensionArc {
                    center_point: v3(c),
                    first_extension_point: at(start),
                    second_extension_point: at(end),
                    arc_start_parameter: start,
                    arc_end_parameter: end,
                    ..DimensionArc::default()
                };
                d.base.actual_measurement = r * (end - start);
                let mut d = Dimension::Arc(d);
                d.set_definition_point(v3(point));
                vec![d]
            }
            DimSpec::Ordinate {
                feature,
                leader_end,
            } => {
                finite(&[feature, leader_end])?;
                let d = sub(leader_end, feature);
                if unit(d).is_none() {
                    return Err(invalid("The leader must leave the feature"));
                }
                // A leader running up or down shows the X ordinate.
                let x = d[1].abs() >= d[0].abs();
                vec![Dimension::Ordinate(DimensionOrdinate::new(
                    v3(feature),
                    v3(leader_end),
                    x,
                ))]
            }
            DimSpec::Baseline { from, points } => return self.chain(&from, &points, false),
            DimSpec::Continue { from, points } => return self.chain(&from, &points, true),
            DimSpec::Quick {
                targets,
                line_point,
            } => {
                finite(&[line_point])?;
                if targets.is_empty() {
                    return Err(invalid("Pick the entities first"));
                }
                let mut out = Vec::with_capacity(targets.len());
                for target in &targets {
                    out.push(self.quick(target, line_point)?);
                }
                out
            }
        };
        Ok(out)
    }

    /// Baseline (`continued` false) or continued dimensions from the linear or aligned dimension
    /// `from` to each of `points`.
    fn chain(
        &self,
        from: &Target,
        points: &[[f64; 2]],
        continued: bool,
    ) -> Result<Vec<Dimension>, CoreError> {
        finite(points)?;
        if points.is_empty() {
            return Err(invalid("Give the points to dimension to"));
        }
        let (_, base) = self.linear_target(from)?;
        let (p1, p2, d, axis) = linear_parts(&base).expect("checked by linear_target");
        let n = [-axis[1], axis[0]];
        let offset = dot(sub(d, p1), n);
        let side = if offset < 0.0 { -1.0 } else { 1.0 };
        let look = DimLook::of(&self.drawing.doc, &base);
        let step = if look.increment > 0.0 {
            look.increment
        } else {
            2.0 * look.text_height
        };
        let angle = axis[1].atan2(axis[0]);
        let aligned = matches!(base, Dimension::Aligned(_));
        let mut out = Vec::with_capacity(points.len());
        let mut last = p2;
        for (i, &p) in points.iter().enumerate() {
            // On the base's own line, or a step further out from it for each baseline.
            let (a, further) = if continued {
                (last, 0.0)
            } else {
                (p1, side * step * (i + 1) as f64)
            };
            let along = dot(sub(p, a), axis);
            if along.abs() < 1e-12 {
                return Err(invalid(
                    "Each point must be away from the last along the dimension",
                ));
            }
            let line_point = [d[0] + n[0] * further, d[1] + n[1] * further];
            let mut dim = linear_dimension(a, p, line_point, angle);
            if aligned {
                // An aligned base gives aligned dimensions along the same direction.
                if let Dimension::Linear(l) = &dim {
                    let mut al = DimensionAligned::new(l.first_point, l.second_point);
                    al.definition_point = l.definition_point;
                    let at = al.definition_point;
                    dim = Dimension::Aligned(al);
                    dim.set_definition_point(at);
                }
            }
            dim.base_mut().style_name = base.base().style_name.clone();
            out.push(dim);
            last = p;
        }
        Ok(out)
    }

    /// QDIM's dimension of one entity: a line's horizontal or vertical length, its line through
    /// `line_point`; an arc's radius; a circle's diameter.
    fn quick(&self, target: &Target, line_point: [f64; 2]) -> Result<Dimension, CoreError> {
        let h = self.sheet_targets_any(std::slice::from_ref(target))?[0];
        match self.entity(h) {
            EntityType::Line(l) => {
                let (a, b) = (xy(&l.start), xy(&l.end));
                let d = sub(b, a);
                if unit(d).is_none() {
                    return Err(invalid("A line of no length has nothing to dimension"));
                }
                let mid = [(a[0] + b[0]) / 2.0, (a[1] + b[1]) / 2.0];
                Ok(if d[0].abs() >= d[1].abs() {
                    linear_dimension(a, b, [mid[0], line_point[1]], 0.0)
                } else {
                    linear_dimension(a, b, [line_point[0], mid[1]], std::f64::consts::FRAC_PI_2)
                })
            }
            EntityType::Arc(_) | EntityType::Circle(_) => {
                let (c, r, angles) = self.round(target)?;
                let toward = match angles {
                    Some((s, e)) => {
                        let e = if e <= s { e + std::f64::consts::TAU } else { e };
                        (s + e) / 2.0
                    }
                    None => std::f64::consts::FRAC_PI_4,
                };
                let u = [toward.cos(), toward.sin()];
                let on = [c[0] + u[0] * r, c[1] + u[1] * r];
                Ok(if angles.is_some() {
                    Dimension::Radius(DimensionRadius::new(v3(c), v3(on)))
                } else {
                    let far = [c[0] - u[0] * r, c[1] - u[1] * r];
                    Dimension::Diameter(DimensionDiameter::new(v3(far), v3(on)))
                })
            }
            _ => Err(invalid("Quick dimension takes lines, arcs and circles")),
        }
    }

    /// `Command::Dimension`: adds the dimensions `spec` describes, each with its block.
    pub(crate) fn add_dimensions(&mut self, spec: DimSpec) -> Result<Vec<u64>, CoreError> {
        let style = self.dim_style();
        // Baseline and continued dimensions keep the style of the one they go on from.
        let own_style = matches!(spec, DimSpec::Baseline { .. } | DimSpec::Continue { .. });
        let mut dims = self.dimensions_of(spec)?;
        for d in &mut dims {
            let m = d.measurement();
            // An ordinate at the datum reads 0.
            let least = if matches!(d, Dimension::Ordinate(_)) {
                -1.0
            } else {
                1e-12
            };
            if !(m.is_finite() && m > least) {
                return Err(invalid("There is nothing to measure between those points"));
            }
            let base = d.base_mut();
            if !own_style {
                base.style_name = style.clone();
            }
            base.actual_measurement = m;
            if let Some(scale) = self.annotation_dimscale() {
                set_dimscale(&mut base.common, scale);
            }
        }
        let handles = self.add_styled(dims.into_iter().map(EntityType::Dimension).collect())?;
        for &h in &handles {
            self.apply_unit_suffix(Handle::new(h));
            self.rebuild_dimension(Handle::new(h))?;
        }
        Ok(handles)
    }

    fn measured_dimension(&self, d: &Dimension) -> qiyas_geom::DimGeometry {
        let geometry = dimension_entities(&self.drawing.doc, d);
        let xrefs = self.xref_docs();
        let width = geometry.entities.iter().find_map(|e| {
            let flat = flatten(&self.drawing.doc, e, &Xform::identity(), 0.01);
            let text = flat.paths.into_iter().find_map(|p| p.text)?;
            let laid = self.text.borrow_mut().lay_out_text(
                &self.drawing.doc,
                &xrefs,
                &text,
                self.arabic_reversed,
            )?;
            Some(
                (laid.corners[1][0] - laid.corners[0][0])
                    .hypot(laid.corners[1][1] - laid.corners[0][1]),
            )
        });
        qiyas_geom::dimension_entities_with_width(&self.drawing.doc, d, width)
    }

    /// Generates the `*D` block of the dimension `h` again from its points and style (a new one
    /// when it has none), placing its text where the style puts it unless it was moved.
    pub(crate) fn rebuild_dimension(&mut self, h: Handle) -> Result<(), CoreError> {
        let Some(EntityType::Dimension(d)) = self.drawing.doc.get_entity(h) else {
            return Err(invalid("This is no dimension"));
        };
        let mut d = d.clone();
        let geometry = self.measured_dimension(&d);
        {
            let base = d.base_mut();
            if !base.text_user_positioned {
                if let Some(at) = geometry.text_at {
                    base.text_middle_point = v3(at);
                }
            }
            base.common.graphic_data = None;
        }
        let m = d.measurement();
        if m.is_finite() {
            d.base_mut().actual_measurement = m;
        }
        let owner = self.dimension_block(&mut d)?;
        self.register_text_app();
        for mut e in geometry.entities {
            // Its text is in reading order; every part marks the block as Qiyas's own.
            mark_logical(e.common_mut());
            e.common_mut().owner_handle = owner;
            self.drawing
                .doc
                .add_entity(e)
                .map_err(|e| invalid(e.to_string()))?;
        }
        *self.drawing.doc.get_entity_mut(h).expect("found above") = EntityType::Dimension(d);
        Ok(())
    }

    /// The block record `d`'s geometry goes in, emptied: its own `*D` block, or a new one under
    /// the first free `*Dn` name (written into `d`).
    fn dimension_block(&mut self, d: &mut Dimension) -> Result<Handle, CoreError> {
        let doc = &mut self.drawing.doc;
        let name = d.base().block_name.clone();
        if let Some(record) = doc.block_records.get(&name).filter(|_| !name.is_empty()) {
            let (handle, inside) = (record.handle, record.entity_handles.clone());
            for e in inside {
                doc.remove_entity_arc(e);
            }
            if let Some(record) = doc.block_records.get_mut(&name) {
                record.entity_handles.clear();
            }
            return Ok(handle);
        }
        let fresh = (1..)
            .map(|n| format!("*D{n}"))
            .find(|n| doc.block_records.get(n).is_none())
            .expect("a free name");
        let mut record = BlockRecord::new(fresh.clone());
        record.handle = doc.allocate_handle();
        record.block_entity_handle = doc.allocate_handle();
        record.block_end_handle = doc.allocate_handle();
        record.flags.anonymous = true;
        let handle = record.handle;
        doc.block_records
            .add(record)
            .map_err(|e| invalid(e.to_string()))?;
        d.base_mut().block_name = fresh;
        Ok(handle)
    }

    /// The dimension `target` at the top of the sheet.
    fn dimension_target(&self, target: &Target) -> Result<(Handle, Dimension), CoreError> {
        let h = self.sheet_targets(std::slice::from_ref(target))?[0];
        match self.entity(h) {
            EntityType::Dimension(d) => Ok((h, d.clone())),
            _ => Err(invalid("Pick a dimension")),
        }
    }

    /// `Command::DimEdit`: changes the dimension `target` by `op` and rebuilds its block.
    pub(crate) fn dim_edit(&mut self, target: &Target, op: &DimEditOp) -> Result<(), CoreError> {
        let (h, mut d) = self.dimension_target(target)?;
        let base = d.base_mut();
        match op {
            DimEditOp::TextOverride(text) => {
                if text.contains(['\n', '\r']) {
                    return Err(invalid("A dimension's text takes one line"));
                }
                base.set_text_override((!text.is_empty()).then(|| text.clone()));
            }
            DimEditOp::Flip => {
                base.flip_arrow1 = !base.flip_arrow1;
                base.flip_arrow2 = !base.flip_arrow2;
            }
            DimEditOp::MoveText(p) => {
                finite(&[*p])?;
                base.text_middle_point = v3(*p);
                base.text_user_positioned = true;
            }
        }
        *self.drawing.doc.get_entity_mut(h).expect("a sheet target") = EntityType::Dimension(d);
        self.rebuild_dimension(h)
    }

    /// The lines of the dimension `h`'s block, its block built first when it has none.
    fn block_lines(&mut self, h: Handle) -> Result<Vec<BlockLine>, CoreError> {
        let name = match self.entity(h) {
            EntityType::Dimension(d) => d.base().block_name.clone(),
            _ => return Err(invalid("This is no dimension")),
        };
        if name.is_empty() || self.drawing.doc.entities_in_block(&name).next().is_none() {
            self.rebuild_dimension(h)?;
        }
        let name = match self.entity(h) {
            EntityType::Dimension(d) => d.base().block_name.clone(),
            _ => unreachable!("still a dimension"),
        };
        Ok(self
            .drawing
            .doc
            .entities_in_block(&name)
            .filter_map(|e| match e {
                EntityType::Line(l) => Some((l.common.handle, xy(&l.start), xy(&l.end))),
                _ => None,
            })
            .collect())
    }

    /// Replaces the line `line` of a dimension's block by `pieces` (point chains).
    fn replace_line(&mut self, line: Handle, pieces: &[Vec<[f64; 2]>]) -> Result<(), CoreError> {
        let doc = &mut self.drawing.doc;
        let Some(EntityType::Line(original)) = doc.get_entity(line).cloned() else {
            return Ok(());
        };
        doc.remove_entity_arc(line);
        for chain in pieces {
            for pair in chain.windows(2) {
                if unit(sub(pair[1], pair[0])).is_none() {
                    continue;
                }
                let mut l = original.clone();
                l.common.handle = Handle::NULL;
                l.start = v3(pair[0]);
                l.end = v3(pair[1]);
                doc.add_entity(EntityType::Line(l))
                    .map_err(|e| invalid(e.to_string()))?;
            }
        }
        Ok(())
    }

    /// `Command::DimBreak`: a gap (an arrowhead long) in the dimension `target`'s lines wherever
    /// `cutter` crosses them.
    pub(crate) fn dim_break(&mut self, target: &Target, cutter: &Target) -> Result<(), CoreError> {
        let (h, d) = self.dimension_target(target)?;
        let c = self.sheet_targets_any(std::slice::from_ref(cutter))?[0];
        if c == h {
            return Err(invalid("Pick another entity to break the dimension at"));
        }
        let gap = {
            let look = DimLook::of(&self.drawing.doc, &d);
            if look.arrow > 0.0 {
                look.arrow
            } else {
                look.text_height
            }
        };
        let cutting: Vec<([f64; 2], [f64; 2])> = {
            let doc = &self.drawing.doc;
            flatten(doc, self.entity(c), &Xform::identity(), self.measure_tol())
                .into_paths()
                .iter()
                .flat_map(|p| {
                    let mut pts = p.points.clone();
                    if p.closed && pts.len() > 2 {
                        pts.push(pts[0]);
                    }
                    pts.windows(2).map(|w| (w[0], w[1])).collect::<Vec<_>>()
                })
                .collect()
        };
        let mut broken = false;
        for (line, a, b) in self.block_lines(h)? {
            let len = sub(b, a)[0].hypot(sub(b, a)[1]);
            let mut cuts: Vec<f64> = cutting
                .iter()
                .filter_map(|&(p, q)| crossing_param(a, b, p, q))
                .collect();
            if cuts.is_empty() || len < 1e-12 {
                continue;
            }
            cuts.sort_by(f64::total_cmp);
            let half = gap / 2.0 / len;
            let mut pieces = Vec::new();
            let mut from = 0.0;
            for t in cuts {
                let to = (t - half).max(from);
                if to > from {
                    pieces.push(vec![lerp(a, b, from), lerp(a, b, to)]);
                }
                from = (t + half).max(from);
            }
            if from < 1.0 {
                pieces.push(vec![lerp(a, b, from), b]);
            }
            self.replace_line(line, &pieces)?;
            broken = true;
        }
        if broken {
            Ok(())
        } else {
            Err(invalid("That entity does not cross the dimension's lines"))
        }
    }

    /// `Command::DimJogLine`: a jog in the linear or aligned dimension `target`'s line at the
    /// point on it nearest `at`.
    pub(crate) fn dim_jog_line(&mut self, target: &Target, at: [f64; 2]) -> Result<(), CoreError> {
        finite(&[at])?;
        let (h, d) = self.linear_target(target)?;
        let (_, _, def, axis) = linear_parts(&d).expect("a linear dimension");
        let n = [-axis[1], axis[0]];
        let size = 1.5 * DimLook::of(&self.drawing.doc, &d).text_height;
        let along = |p: [f64; 2]| dot(sub(p, def), axis);
        let on_line = |p: [f64; 2]| dot(sub(p, def), n).abs() < 1e-9 * (1.0 + size);
        let q = along(at);
        let found = self.block_lines(h)?.into_iter().find(|&(_, a, b)| {
            on_line(a) && on_line(b) && {
                let (s, e) = (along(a).min(along(b)), along(a).max(along(b)));
                q - size / 2.0 > s && q + size / 2.0 < e
            }
        });
        let Some((line, a, b)) = found else {
            return Err(invalid(
                "Pick a point on the dimension line, away from its ends",
            ));
        };
        let dir = if along(b) >= along(a) { 1.0 } else { -1.0 };
        let point = |t: f64, k: f64| {
            [
                def[0] + axis[0] * (q + dir * t) + n[0] * k,
                def[1] + axis[1] * (q + dir * t) + n[1] * k,
            ]
        };
        let zigzag = vec![
            a,
            point(-size / 2.0, 0.0),
            point(-size / 6.0, size / 2.0),
            point(size / 6.0, -size / 2.0),
            point(size / 2.0, 0.0),
            b,
        ];
        self.replace_line(line, &[zigzag])
    }

    /// The automatic spacing follows the base dimension's style and text-height overrides.
    pub(crate) fn dimension_spacing_default(&self, base: &Target) -> Result<f64, CoreError> {
        let (_, dimension) = self.linear_target(base)?;
        Ok(2.0 * DimLook::of(&self.drawing.doc, &dimension).text_height)
    }

    /// `Command::DimSpace`: the linear or aligned dimensions `targets`, parallel to `base`, get
    /// their lines `spacing` apart going out from `base`'s (none: twice the text height), in the
    /// order they were out from it.
    pub(crate) fn dim_space(
        &mut self,
        base: &Target,
        targets: &[Target],
        spacing: Option<f64>,
    ) -> Result<(), CoreError> {
        if targets.is_empty() {
            return Err(invalid("Pick the dimensions to space"));
        }
        let (bh, b) = self.linear_target(base)?;
        let (_, _, bdef, axis) = linear_parts(&b).expect("checked");
        let n = [-axis[1], axis[0]];
        let step = match spacing {
            Some(s) if s > 0.0 && s.is_finite() => s,
            Some(_) => return Err(invalid("The spacing must be more than 0")),
            None => self.dimension_spacing_default(base)?,
        };
        let mut placed = Vec::with_capacity(targets.len());
        for t in targets {
            let (h, d) = self.linear_target(t)?;
            if h == bh {
                continue;
            }
            let (_, _, def, ax) = linear_parts(&d).expect("checked");
            if (ax[0] * axis[1] - ax[1] * axis[0]).abs() > 1e-9 {
                return Err(invalid("The dimensions must be parallel to the base one"));
            }
            placed.push((dot(sub(def, bdef), n), h, d));
        }
        let side = if placed.iter().map(|p| p.0).sum::<f64>() < 0.0 {
            -1.0
        } else {
            1.0
        };
        placed.sort_by(|a, b| (side * a.0).total_cmp(&(side * b.0)));
        for (i, (now, h, mut d)) in placed.into_iter().enumerate() {
            let want = side * step * (i + 1) as f64;
            let shift = [n[0] * (want - now), n[1] * (want - now)];
            let (_, _, def, _) = linear_parts(&d).expect("checked");
            d.set_definition_point(v3([def[0] + shift[0], def[1] + shift[1]]));
            let base = d.base_mut();
            if base.text_user_positioned {
                base.text_middle_point.x += shift[0];
                base.text_middle_point.y += shift[1];
            }
            *self.drawing.doc.get_entity_mut(h).expect("a sheet target") = EntityType::Dimension(d);
            self.rebuild_dimension(h)?;
        }
        Ok(())
    }

    /// `Command::Leader` (and `MLeader`, which adds a short landing): a leader through `points`
    /// with its arrowhead at the first, and `text` (when any) as an MText beside the last, in the
    /// current dimension style at the annotation scale. The leader's handle, then the text's.
    pub(crate) fn add_leader(
        &mut self,
        points: &[[f64; 2]],
        text: &str,
        landing: bool,
    ) -> Result<Vec<u64>, CoreError> {
        finite(points)?;
        if points.len() < 2 || points.windows(2).any(|w| unit(sub(w[1], w[0])).is_none()) {
            return Err(invalid("A leader needs two or more different points"));
        }
        let style = self.dim_style();
        let own_scale = self.annotation_dimscale();
        let mut leader = Leader::new();
        leader.dimension_style = style.clone();
        if let Some(scale) = own_scale {
            set_dimscale(&mut leader.common, scale);
        }
        let look = DimLook::named(&self.drawing.doc, &style, &leader.common);
        let mut vertices: Vec<[f64; 2]> = points.to_vec();
        let last = vertices[vertices.len() - 1];
        let before = vertices[vertices.len() - 2];
        let right = last[0] >= before[0];
        let sign = if right { 1.0 } else { -1.0 };
        if landing {
            vertices.push([
                last[0] + sign * 2.0 * look.arrow.max(look.text_height),
                last[1],
            ]);
        }
        let end = vertices[vertices.len() - 1];
        leader.vertices = vertices.iter().map(|&p| v3(p)).collect();
        leader.text_height = look.text_height;
        leader.arrow_size = look.arrow;
        leader.dimension_gap = look.gap;
        let text = text.trim_end_matches('\n');
        if text.trim().is_empty() {
            leader.creation_type = LeaderCreationType::NoAnnotation;
            return self.add_styled(vec![EntityType::Leader(leader)]);
        }
        let doc = &mut self.drawing.doc;
        let (lh, th) = (doc.allocate_handle(), doc.allocate_handle());
        leader.common.handle = lh;
        leader.creation_type = LeaderCreationType::WithText;
        leader.annotation_handle = th;
        let mut note =
            MText::with_value(escape_mtext(text), v3([end[0] + sign * look.gap, end[1]]))
                .with_height(look.text_height);
        note.common.handle = th;
        note.common.reactors = vec![lh];
        note.attachment_point = if right {
            AttachmentPoint::MiddleLeft
        } else {
            AttachmentPoint::MiddleRight
        };
        note.style = if doc.text_styles.get(&look.text_style).is_some() {
            look.text_style.clone()
        } else {
            self.text_style()
        };
        self.register_text_app();
        mark_logical(&mut note.common);
        leader.text_width = 0.0;
        self.add_styled(vec![EntityType::Leader(leader), EntityType::MText(note)])
    }

    /// `Command::Tolerance`: a feature control frame `frame` (AutoCAD's codes: `{\Fgdt;p}` a
    /// symbol, `%%v` between fields, `^J` between rows) with its left middle at `at`.
    pub(crate) fn add_tolerance(&mut self, at: [f64; 2], frame: &str) -> Result<u64, CoreError> {
        finite(&[at])?;
        if frame.trim().is_empty() {
            return Err(invalid("Type the tolerance first"));
        }
        let style = self.dim_style();
        let mut tol = Tolerance::with_text(v3(at), frame);
        tol.dimension_style_name = style.clone();
        if let Some(scale) = self.annotation_dimscale() {
            set_dimscale(&mut tol.common, scale);
        }
        let look = DimLook::named(&self.drawing.doc, &style, &tol.common);
        tol.text_height = look.text_height;
        tol.dimension_gap = look.gap;
        Ok(self.add_styled(vec![EntityType::Tolerance(tol)])?[0])
    }
}

/// Where along `a`-`b` (0 to 1) the segment `p`-`q` crosses it, if it does.
fn crossing_param(a: [f64; 2], b: [f64; 2], p: [f64; 2], q: [f64; 2]) -> Option<f64> {
    let (r, s) = (sub(b, a), sub(q, p));
    let den = r[0] * s[1] - r[1] * s[0];
    if den.abs() < 1e-15 {
        return None;
    }
    let ap = sub(p, a);
    let t = (ap[0] * s[1] - ap[1] * s[0]) / den;
    let u = (ap[0] * r[1] - ap[1] * r[0]) / den;
    ((0.0..=1.0).contains(&t) && (0.0..=1.0).contains(&u)).then_some(t)
}

fn lerp(a: [f64; 2], b: [f64; 2], t: f64) -> [f64; 2] {
    [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t]
}

/// Whether Qiyas generated the dimension's block (its parts carry `LOGICAL_TEXT_APP`).
fn generated_block(doc: &CadDocument, d: &Dimension) -> bool {
    let block = &d.base().block_name;
    !block.is_empty()
        && doc
            .entities_in_block(block)
            .any(|part| is_logical_text(part.common()))
}

impl Session {
    /// Search both sides of the measured points. Only the dimension line moves; measurement
    /// endpoints remain exact. Grid bubbles, annotation and text against geometry are obstacles.
    pub(crate) fn place_dimension_clear(
        &mut self,
        handle: Handle,
        clearance_mm: f64,
    ) -> Result<(), CoreError> {
        if !clearance_mm.is_finite() || clearance_mm < 0.0 {
            return Err(invalid("Clearance must be non-negative"));
        }
        let Some(EntityType::Dimension(original)) = self.drawing.doc.get_entity(handle) else {
            return Err(invalid("Choose a dimension"));
        };
        let original = original.clone();
        let Some((p1, p2, def, axis)) = linear_parts(&original) else {
            return Err(invalid(
                "Automatic placement supports linear and aligned dimensions",
            ));
        };
        let ink = self.sheet_ink(&self.sheet);
        if !ink.incomplete.is_empty() {
            return Err(invalid("The drawing could not be checked completely"));
        }
        let normal = [-axis[1], axis[0]];
        let step = self.paper_distance(7.5);
        let clearance = self.paper_distance(clearance_mm);
        // Parallel chains normally share extension lines. Their lines and arrowheads
        // may meet there, while their labels must still remain clear of all ink.
        let tolerance = 0.0002 / self.check_space(&self.sheet).0;
        let shared_extensions: Vec<_> = self
            .drawing
            .entities_in(&self.sheet)
            .filter_map(|entity| {
                let EntityType::Dimension(other) = entity else {
                    return None;
                };
                let (a, b, at, direction) = linear_parts(other)?;
                let parallel = (direction[0] * axis[1] - direction[1] * axis[0]).abs() < 1e-9;
                let shared = [a, b].iter().any(|a| {
                    [p1, p2]
                        .iter()
                        .any(|b| (a[0] - b[0]).hypot(a[1] - b[1]) <= tolerance)
                });
                (parallel && shared).then_some((entity.common().handle.value(), at))
            })
            .collect();
        let mid = [(p1[0] + p2[0]) * 0.5, (p1[1] + p2[1]) * 0.5];
        let mut candidates = vec![def];
        for i in 1..=40 {
            for side in [-1.0, 1.0] {
                candidates.push([
                    mid[0] + normal[0] * step * i as f64 * side,
                    mid[1] + normal[1] * step * i as f64 * side,
                ]);
            }
        }
        // Keep a clear manual text position first. If the centre falls on an axis or
        // another label, also try small text shifts along the dimension line.
        let candidates =
            std::iter::once((def, None)).chain(candidates.into_iter().flat_map(|at| {
                [0.0, -1.0, 1.0, -2.0, 2.0]
                    .into_iter()
                    .map(move |along| (at, Some(along * step)))
            }));
        for (at, along) in candidates {
            let mut d = original.clone();
            d.set_definition_point(v3(at));
            if let Some(along) = along {
                d.base_mut().text_user_positioned = false;
                if along != 0.0 {
                    if let Some(text_at) = self.measured_dimension(&d).text_at {
                        let base = d.base_mut();
                        base.text_middle_point =
                            v3([text_at[0] + axis[0] * along, text_at[1] + axis[1] * along]);
                        base.text_user_positioned = true;
                    }
                }
            }
            let geometry = self.measured_dimension(&d);
            let mut clear = true;
            let xrefs = self.xref_docs();
            let mut engine = self.text.borrow_mut();
            for e in geometry.entities {
                for flat in flatten(
                    &self.drawing.doc,
                    &e,
                    &Xform::identity(),
                    0.0002 / self.drawing.units.to_metres(),
                )
                .paths
                {
                    let is_text = flat.text.is_some();
                    let points = if let Some(t) = flat.text {
                        engine
                            .lay_out_text(&self.drawing.doc, &xrefs, &t, self.arabic_reversed)
                            .map(|l| l.corners.to_vec())
                            .unwrap_or_default()
                    } else {
                        flat.path.points
                    };
                    if points.is_empty() {
                        continue;
                    }
                    let b = crate::ink::expand(crate::ink::bounds(&points), clearance);
                    if ink.near(b).any(|obstacle| {
                        if obstacle.owner == handle.value() {
                            return false;
                        }
                        if !is_text
                            && obstacle.text.is_none()
                            && shared_extensions.iter().any(|(owner, other_at)| {
                                *owner == obstacle.owner
                                    && dot(sub(at, *other_at), normal).abs()
                                        >= clearance + self.paper_distance(2.5)
                            })
                        {
                            return false;
                        }
                        let bubble = crate::check_layout::grid_bubble(self, &ink, obstacle);
                        if !is_text && !obstacle.annotation && !bubble {
                            return false;
                        }
                        if is_text || obstacle.filled || bubble {
                            obstacle.hits_polygon(&crate::ink::corners(b))
                        } else {
                            crate::ink::edges(&points, flat.path.closed).any(|(a, b)| {
                                obstacle
                                    .edges()
                                    .any(|(c, d)| crate::ink::crosses(a, b, c, d))
                            })
                        }
                    }) {
                        clear = false;
                        break;
                    }
                }
                if !clear {
                    break;
                }
            }
            drop(engine);
            drop(xrefs);
            if clear {
                *self
                    .drawing
                    .doc
                    .get_entity_mut(handle)
                    .expect("dimension exists") = EntityType::Dimension(d);
                self.rebuild_dimension(handle)?;
                return Ok(());
            }
        }
        Err(invalid(
            "No clear dimension position was found; move nearby annotation or choose another side",
        ))
    }
}
